            Some(inherited) if raw_prop.description.is_empty() => (*inherited).to_owned(),
            Some(_) | None => raw_prop.description.clone(),
        };

        chain.props.push(ctx.share(ParsedProp::new(
            raw_prop.name.clone(),
            prop_type,
            raw_prop.required,
            default_value,
            description,
            raw_prop.tags.clone(),
            Some(parent.clone()),
            vec![parent.clone()],
        )));
    }

    chain
}

