        let values: Vec<EnumValue> = arr
            .elements
            .iter()
            .filter_map(|el| match el {
                ArrayExpressionElement::SpreadElement(spread) => match &spread.argument {
                    Expression::Identifier(id) => Some(EnumValue::Spread { spread: id.name.as_str().to_owned() }),
                    _ => None,
