/// Extractor changes that keep the shape are covered by `CacheHeader::fingerprint` instead.
/// 16: `LexedExport::LocalDeclaration` gained `declared_as`.
/// 17: component mappings record whether they are exported.
/// 18: generic functions' result types, and the callee of a wrapper-built component.
/// 19: a mapped type records its key variable and `?` modifier.
/// 20: type parameter defaults.
/// 21: the `ImportedMemberAlias` detection rule.
/// 22: component mappings record the type parameters of the functions they contain.
/// 25: the `TaggedFactory` detection rule.
/// 26: function parameters record whether they are optional or rest.
/// 28: the `FactoryResult` detection rule, and function results recorded for more functions.
/// 30: `SourceData::enum_declarations`.
/// 31: `SourceData::enum_declarations` records each declaration's scope, and `interface_scopes`, `type_alias_scopes`
///     and `class_scopes` record where the other declarations sit.
const CACHE_SCHEMA_VERSION: u32 = 31;

const DATA_FILE: &str = "dts.msgpack";

/// Written first in the payload, so a cache written by a different build is recognized before its entries are decoded.
/// The manifest repeats it for inspection only.
#[derive(Serialize, Deserialize, PartialEq, Debug)]
struct CacheHeader {
    schema: u32,
    version: String,
    /// A hash of this crate's sources and locked dependencies (see `build.rs`): any change to the code that produces
    /// `SourceData` invalidates the cache, bumped or not.
    fingerprint: String,
}

impl CacheHeader {
    fn current() -> CacheHeader {

export const Panel = make<PanelProps>((props) => <div />);
"#;

fn fixture() -> SourceData {
    parse_file(Utf8Path::new("/golden/button.tsx"), FIXTURE)
}

#[test]
fn fixture_populates_every_source_data_field() {
    let SourceData {
        interfaces,
        type_aliases,
        type_alias_params,
        interface_type_params,
        enums,
        const_arrays,
        component_mappings,
        imports,
        exports,
        diagnostics,
        function_results,
        type_param_defaults,
        enum_declarations,
        interface_scopes,
        type_alias_scopes,
        class_scopes,
    } = fixture();
    let fields = [
        ("interfaces", interfaces.is_empty()),
        ("type_aliases", type_aliases.is_empty()),
        ("type_alias_params", type_alias_params.is_empty()),
        ("interface_type_params", interface_type_params.is_empty()),
        ("enums", enums.is_empty()),
        ("const_arrays", const_arrays.is_empty()),
        ("component_mappings", component_mappings.is_empty()),
        ("imports", imports.is_empty()),
        ("exports", exports.is_empty()),
        ("diagnostics", diagnostics.is_empty()),
        ("function_results", function_results.is_empty()),
        ("type_param_defaults", type_param_defaults.is_empty()),
        ("enum_declarations", enum_declarations.is_empty()),
        ("interface_scopes", interface_scopes.is_empty()),
        ("type_alias_scopes", type_alias_scopes.is_empty()),
        ("class_scopes", class_scopes.is_empty()),
    ];
    let empty: Vec<&str> = fields.iter().filter(|(_, is_empty)| *is_empty).map(|(name, _)| *name).collect();
    assert_eq!(empty, Vec::<&str>::new(), "extend FIXTURE so the golden bytes cover these fields");
}

#[test]
fn source_data_bytes_are_stable_for_the_current_schema_version() {
    let bytes = rmp_serde::to_vec(&fixture()).unwrap();
    let hex: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
    insta::assert_snapshot!(format!("schema {CACHE_SCHEMA_VERSION}\n{hex}"));
}

#[test]
fn source_data_round_trips_through_msgpack() {
    let original = fixture();
    let decoded: SourceData = rmp_serde::from_slice(&rmp_serde::to_vec(&original).unwrap()).unwrap();
    assert_eq!(serde_json::to_value(&decoded).unwrap(), serde_json::to_value(&original).unwrap());
}

#[test]
fn a_blob_from_the_previous_schema_version_is_rejected() {
    let dir = std::env::temp_dir().join(format!("caliper-golden-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let cache_dir = camino::Utf8PathBuf::from_path_buf(dir.join("cache")).unwrap();
    let source_path = camino::Utf8PathBuf::from_path_buf(dir.join("button.d.ts")).unwrap();
    std::fs::write(&source_path, FIXTURE).unwrap();

